data={k:{} for k in tsid}
for ts,tsid_val in [( 'temp',tsid['temp']),('heat',tsid['heat']),('cool',tsid['cool'])]:
    for row in csv.reader(open(VALUES_CSV)):
        if row[0]==tsid_val and row[1].startswith('2018-04-12'):
            data[ts][row[1]]=row[2]
hours=sorted(data['temp'])
print('num hours', len(hours))
outside=0
for h in hours:
    t=float(data['temp'][h]); heat=float(data['heat'][h]); cool=float(data['cool'][h])
    if t<heat or t>cool:
        outside+=1
    print(h,t,heat,cool, (t<heat) or (t>cool))
print('outside', outside)
